mapper.select:
SELECT DISTINCT m.* FROM sys_menu m INNER JOIN sys_role_menu rm ON m.id = rm.menu_id INNER JOIN sys_employee_role er ON rm.role_id = er.role_id WHERE er.employee_id = #{employeeId} AND m.del_flag = 0 AND m.status = 0 AND m.visible = 0
AND m.platform = #{platform}
ORDER BY m.sort_order ASC
